import { prepareTopologyRenderFrame, type TopologyRenderOccupant, type TopologyRenderRelationship } from "./renderPipeline.ts";
import { renderTopologyGridMarkup } from "./TopologyGridRenderer.ts";
import { createTopologyTransitionController, type TopologyTransitionController } from "./topologyTransition.ts";
import type { ConnectorRoutingMode } from "./connectorRouting.ts";
import type { HexCell } from "./hex.ts";

export interface TopologyDataset {
  nodes: TopologyRenderOccupant[];
  relationships?: TopologyRenderRelationship[];
  connectorRouting?: ConnectorRoutingMode;
}

export interface TopologyDatasetTransitionOptions {
  sceneGrid: SVGSVGElement;
  cells: HexCell[];
  radius: number;
  connectorRouting?: ConnectorRoutingMode;
  duration?: number;
  reducedMotion?: boolean | (() => boolean);
}

export interface TopologyDatasetTransition {
  getCurrentDataset(): TopologyDataset | null;
  transition(dataset: TopologyDataset): Promise<void>;
  cancel(): void;
  destroy(): void;
}

const svgNamespace = "http://www.w3.org/2000/svg";

function createContentLayer(sceneGrid: SVGSVGElement, name: "current" | "incoming") {
  const layer = document.createElementNS(svgNamespace, "g");
  layer.setAttribute("data-topology-dataset-layer", name);
  sceneGrid.append(layer);
  return layer;
}

function clearLayer(layer: SVGGElement) {
  while (layer.firstChild) layer.firstChild.remove();
}

function appendRenderedContent(
  layer: SVGGElement,
  markup: string,
) {
  clearLayer(layer);
  const parsed = document.createElementNS(svgNamespace, "svg");
  parsed.innerHTML = markup;
  const connectorGroup = parsed.querySelector(".grid-connectors");
  const occupantGroup = parsed.querySelector(".grid-occupants");

  if (connectorGroup) layer.append(connectorGroup);
  if (occupantGroup) layer.append(occupantGroup);
}

export function createTopologyDatasetTransition({
  sceneGrid,
  cells,
  radius,
  connectorRouting = "straight",
  duration = 1700,
  reducedMotion = false,
}: TopologyDatasetTransitionOptions): TopologyDatasetTransition {
  const existingConnectors = sceneGrid.querySelector(".grid-connectors");
  const existingOccupants = sceneGrid.querySelector(".grid-occupants");
  const currentLayer = createContentLayer(sceneGrid, "current");
  const incomingLayer = createContentLayer(sceneGrid, "incoming");

  if (existingConnectors) currentLayer.append(existingConnectors);
  if (existingOccupants) currentLayer.append(existingOccupants);

  const controller: TopologyTransitionController = createTopologyTransitionController({
    duration,
    reducedMotion,
  });
  let activeLayer = currentLayer;
  let stagingLayer = incomingLayer;
  let currentDataset: TopologyDataset | null = null;
  let generation = 0;

  function renderDataset(dataset: TopologyDataset) {
    const frame = prepareTopologyRenderFrame({
      cells,
      occupants: dataset.nodes,
      relationships: dataset.relationships ?? [],
    });
    return renderTopologyGridMarkup({
      frame,
      radius,
      showNodes: true,
      connectorRouting: dataset.connectorRouting ?? connectorRouting,
      className: "topology-dataset-content",
    });
  }

  async function transition(dataset: TopologyDataset) {
    const transitionGeneration = ++generation;
    appendRenderedContent(stagingLayer, renderDataset(dataset));
    stagingLayer.style.opacity = "0";
    stagingLayer.style.pointerEvents = "none";

    await controller.run({
      outgoing: { element: activeLayer },
      incoming: { element: stagingLayer },
    });

    if (transitionGeneration !== generation) return;
    clearLayer(activeLayer);
    activeLayer.style.opacity = "0";
    activeLayer.style.pointerEvents = "none";
    stagingLayer.style.opacity = "1";
    stagingLayer.style.pointerEvents = "auto";
    const previousActive = activeLayer;
    activeLayer = stagingLayer;
    stagingLayer = previousActive;
    currentDataset = dataset;
  }

  return {
    getCurrentDataset() {
      return currentDataset;
    },
    transition,
    cancel() {
      generation += 1;
      controller.cancel();
    },
    destroy() {
      generation += 1;
      controller.cancel();
      clearLayer(activeLayer);
      clearLayer(stagingLayer);
      activeLayer.remove();
      stagingLayer.remove();
    },
  };
}
